pub fn paths(n: Int, edges: List[List[Int]], src: Int) -> List[Int] {
  var dist: List[Int] = []
  var done: List[Bool] = []
  for i in range(0, n) {
    dist = dist.push(-1)
    done = done.push(false)
  }
  if src < 0 or src >= n {
    return dist
  }
  dist = dist.set(src, 0)
  var steps = 0
  while steps < n {
    var best = -1
    for i in range(0, n) {
      let d = dist.get_or(i, -1)
      if d >= 0 and done.get_or(i, true) == false {
        if best < 0 or d < dist.get_or(best, -1) {
          best = i
        }
      }
    }
    if best < 0 {
      break
    }
    let u = best
    let du = dist.get_or(u, 0)
    done = done.set(u, true)
    for e in edges {
      if e.get_or(0, -1) == u {
        let v = e.get_or(1, 0)
        let nd = du + e.get_or(2, 0)
        let cur = dist.get_or(v, -1)
        if cur < 0 or nd < cur {
          dist = dist.set(v, nd)
        }
      }
    }
    steps = steps + 1
  }
  return dist
}
